public void ProcessValues()
{
    int a = 10;
    int b;

    // ref: must be initialized before passing
    Increment(ref a); // a is now 11

    // out: assigned inside method, no initialization needed
    TryParse("42", out b); // b is 42

    // in: read-only, passed by reference
    PrintIn(in a);

    // Optional parameter
    Greet("World");            // uses default greeting
    Greet("World", "Hello");  // uses custom greeting
}

void Increment(ref int value) => value++;
