// Two Sum: find indices of two numbers that add up to target
// Time: O(n), Space: O(n)
public static int[] TwoSum(int[] nums, int target)
{
    var seen = new Dictionary<int, int>();

    for (int i = 0; i < nums.Length; i++)
    {
        int complement = target - nums[i];
        if (seen.ContainsKey(complement))
        {
            return [seen[complement], i];
        }
        seen[nums[i]] = i;
    }

    return Array.Empty<int>();
}

// Check if a string is a palindrome
// Time: O(n), Space: O(1)
public static bool IsPalindrome(string s)
{
    if (string.IsNullOrEmpty(s)) return true;

    int left = 0;
    int right = s.Length - 1;

    while (left < right)
    {
        if (char.ToLower(s[left]) != char.ToLower(s[right]))
            return false;
        left++;
        right--;
    }

    return true;
}

// Fibonacci: iterative O(n) time, O(1) space
public static int Fibonacci(int n)
{
    if (n <= 1) return n;

    int a = 0, b = 1;
    for (int i = 2; i <= n; i++)
    {
        int temp = b;
        b = a + b;
        a = temp;
    }
    return b;
}

// Recursive with memoization
public static int FibonacciMemo(int n, Dictionary<int, int>? memo = null)
{
    memo ??= new Dictionary<int, int>();
    if (n <= 1) return n;
    if (memo.ContainsKey(n)) return memo[n];
    memo[n] = FibonacciMemo(n - 1, memo) + FibonacciMemo(n - 2, memo);
    return memo[n];
}

// Classic FizzBuzz: print 1-100, replace multiples of 3 with Fizz,
// multiples of 5 with Buzz, multiples of both with FizzBuzz
// Time: O(n), Space: O(1)
public static void FizzBuzz(int n = 100)
{
    for (int i = 1; i <= n; i++)
    {
        if (i % 15 == 0)
            Console.WriteLine("FizzBuzz");
        else if (i % 3 == 0)
            Console.WriteLine("Fizz");
        else if (i % 5 == 0)
            Console.WriteLine("Buzz");
        else
            Console.WriteLine(i);
    }
}

// More concise with switch expression
public static string FizzBuzzSwitch(int i) => i % 15 switch
{
    0 => "FizzBuzz",
    _ when i % 3 == 0 => "Fizz",
    _ when i % 5 == 0 => "Buzz",
    _ => i.ToString()
};

// Reverse a string in C#
// Time: O(n), Space: O(n)
public static string ReverseString(string s)
{
    if (string.IsNullOrEmpty(s)) return s;
    char[] chars = s.ToCharArray();
    Array.Reverse(chars);
    return new string(chars);
}

// In-place reverse for char array
public static void ReverseInPlace(char[] chars)
{
    int left = 0, right = chars.Length - 1;
    while (left < right)
    {
        (chars[left], chars[right]) = (chars[right], chars[left]);
        left++;
        right--;
    }
}

// Check if parentheses, brackets, and braces are balanced
// Time: O(n), Space: O(n)
public static bool IsValidParentheses(string s)
{
    var stack = new Stack<char>();
    var pairs = new Dictionary<char, char> { { ')', '(' }, { '}', '{' }, { ']', '[' } };

    foreach (char c in s)
    {
        if (c is '(' or '{' or '[')
        {
            stack.Push(c);
        }
        else if (pairs.ContainsKey(c))
        {
            if (stack.Count == 0 || stack.Pop() != pairs[c])
                return false;
        }
    }

    return stack.Count == 0;
}
